using System;using System.IO;using System.Reflection;using System.Linq;using IdleRestaurant;using UnityEngine;
public static class SaveCheck{public static object Main(){var app=UnityEngine.Object.FindAnyObjectByType<RestaurantApp>();app.Save();var store=(SaveStore)typeof(RestaurantApp).GetField("store",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(app);bool recovered;var saved=store.Read(out recovered);var g=new RestaurantGame(app.catalog,saved);if(recovered||Math.Abs(g.State.cash-app.Game.State.cash)>.00001||g.TeamCount!=app.Game.TeamCount||g.TotalWaves()!=app.Game.TotalWaves()||g.State.outlets.Count(o=>o.open)!=app.Game.State.outlets.Count(o=>o.open))throw new Exception("Live disk save roundtrip mismatch");var result=new{utc=DateTime.UtcNow,status="PASS",sessionSeconds=app.Game.State.seconds,cash=g.State.cash,managers=g.TeamCount,outlets=g.State.outlets.Count(o=>o.open),waves=g.TotalWaves(),recoveredBackup=recovered,scope="Actual current fresh-session save written then read through SaveStore, without replacing the running model"};Directory.CreateDirectory(Path.GetFullPath("Recordings/FreshSession051"));File.WriteAllText(Path.GetFullPath("Recordings/FreshSession051/LiveSaveCheck.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}}
